// Some portions generated by Codex
package org.eclipse.rdf4j.sail.nativerdf;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.nio.file.Path;

import org.eclipse.rdf4j.common.transaction.IsolationLevels;
import org.eclipse.rdf4j.model.BNode;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.sail.nativerdf.model.NativeValue;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class NativeBlankNodeReferenceLifecycleTest {

	private static final String ID = "native-reference-lifecycle";
	private static final String QUERY = "ASK { <_:" + ID + "> <urn:lifecycle:p> ?value }";

	@Test
	void preparedReferenceTracksCommitDeleteReinsertAndPersistentReopen(@TempDir Path directory) throws Exception {
		BNode expected = SimpleValueFactory.getInstance().createBNode(ID);
		SailRepository repository = new SailRepository(new NativeStore(directory.toFile(), "spoc,posc"));
		repository.init();
		try {
			try (var connection = repository.getConnection()) {
				var dictionary = (ValueStore) repository.getValueFactory();
				var ask = connection.prepareBooleanQuery(QUERY);
				assertEquals(NativeValue.UNKNOWN_ID, dictionary.getID(expected),
						"preparing an absent fixed reference must not intern it");
				assertFalse(ask.evaluate());
				assertEquals(NativeValue.UNKNOWN_ID, dictionary.getID(expected),
						"evaluating an absent fixed reference must not write the dictionary");

				connection.begin();
				connection.add(expected, SimpleValueFactory.getInstance().createIRI("urn:lifecycle:p"),
						SimpleValueFactory.getInstance().createLiteral("first"));
				connection.commit();
				assertTrue(ask.evaluate(), "the same prepared reference must observe the committed statement");

				connection.begin();
				connection.remove(expected, SimpleValueFactory.getInstance().createIRI("urn:lifecycle:p"), null);
				connection.commit();
				assertFalse(ask.evaluate(), "deletion must invalidate a previous positive reference result");

				connection.begin();
				connection.add(expected, SimpleValueFactory.getInstance().createIRI("urn:lifecycle:p"),
						SimpleValueFactory.getInstance().createLiteral("second"));
				connection.commit();
				assertTrue(ask.evaluate(), "reusing the same lexical ID must restore the exact fixed identity");
				int storedId = dictionary.getID(expected);
				assertNotEquals(NativeValue.UNKNOWN_ID, storedId);
				assertEquals(expected, dictionary.getValue(storedId));
			}
		} finally {
			repository.shutDown();
		}

		SailRepository reopened = new SailRepository(new NativeStore(directory.toFile(), "spoc,posc"));
		reopened.init();
		try {
			try (var connection = reopened.getConnection()) {
				var dictionary = (ValueStore) reopened.getValueFactory();
				int reopenedId = dictionary.getID(expected);
				assertNotEquals(NativeValue.UNKNOWN_ID, reopenedId,
						"the live blank-node's lexical identity must survive reopen");
				assertEquals(expected, dictionary.getValue(reopenedId));
				assertTrue(connection.prepareBooleanQuery(QUERY).evaluate());
			}
		} finally {
			reopened.shutDown();
		}
	}

	@Test
	void activeSnapshotDoesNotSeeLaterReferenceInsertUntilNextExecution(@TempDir Path directory) throws Exception {
		BNode expected = SimpleValueFactory.getInstance().createBNode(ID + "-snapshot");
		String queryText = "ASK { <_:" + expected.getID() + "> <urn:lifecycle:p> ?value }";
		SailRepository repository = new SailRepository(new NativeStore(directory.toFile(), "spoc,posc"));
		repository.init();
		try {
			try (var reader = repository.getConnection(); var writer = repository.getConnection()) {
				var ask = reader.prepareBooleanQuery(queryText);
				reader.begin(IsolationLevels.SNAPSHOT);
				assertFalse(ask.evaluate());

				writer.begin(IsolationLevels.SNAPSHOT);
				writer.add(expected, SimpleValueFactory.getInstance().createIRI("urn:lifecycle:p"),
						SimpleValueFactory.getInstance().createLiteral("committed later"));
				writer.commit();
				assertFalse(ask.evaluate(), "an active read snapshot must not observe a later committed insert");

				reader.commit();
				assertTrue(ask.evaluate(), "a new execution after the snapshot ends must resolve the inserted ID");
			}
		} finally {
			repository.shutDown();
		}
	}
}
